package oracle;
import java.util.*;import java.io.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.entity.player.Player;import core.game.world.map.Location;import core.net.packet.IoBuffer;
public class Support{
 static Map input;static TreeMap<String,Player>nodes;static List<Object>events,frames;static Map<String,Integer>calls;static List<List<Player>>views;public static core.net.IoSession session;
 public static class Failure extends RuntimeException{}
 static int n(Object v){return((Number)v).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 static Location loc(Object v){if(v==null)return null;List a=(List)v;return new Location(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 static Object coords(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static Map map(Object...v){Map<String,Object>m=new TreeMap<>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
 static String name(Player p){return p==null?null:p.name;}
 public static void emit(String event,Object...args){List<Object>e=new ArrayList<>();e.add(event);Collections.addAll(e,args);events.add(e);int count=calls.merge(event,1,Integer::sum);for(Object v:(List)input.getOrDefault("hooks",new ArrayList<>())){Map h=(Map)v;if(event.equals(h.get("event"))&&count==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}}
 public static void sent(byte[]bytes){StringBuilder s=new StringBuilder();for(byte x:bytes)s.append(String.format("%02x",x&255));frames.add(s.toString());}
 public static void masks(Player local,Player other,IoBuffer out,boolean appearance,boolean sync){emit("masks",name(local),name(other),appearance,sync);out.put(other.index).put(appearance?1:0).put(sync?1:0);}
 public static List<Player>candidates(Location l,int distance){emit("candidates",coords(l),distance);List<Player>out=new ArrayList<>();for(Object name:(List)input.getOrDefault("candidates",new ArrayList<>()))out.add(nodes.get(name));return out;}
 public static int[]keys(int id){emit("keys",id);return new int[]{id,-id,Integer.MIN_VALUE,Integer.MAX_VALUE};}
 static void set(Player p,Map m){if(m.containsKey("index"))p.index=n(m.get("index"));if(m.containsKey("location"))p.location=loc(m.get("location"));if(m.containsKey("scene"))p.playerFlags.updateSceneGraph=b(m,"scene");if(m.containsKey("teleport"))p.properties.teleporting=b(m,"teleport");if(m.containsKey("active"))p.active=b(m,"active");if(m.containsKey("invisible"))p.invisible=b(m,"invisible");if(m.containsKey("walk"))p.walkingQueue.walkDir=n(m.get("walk"));if(m.containsKey("run"))p.walkingQueue.runDir=n(m.get("run"));if(m.containsKey("direction"))p.direction.value=n(m.get("direction"));if(m.containsKey("required"))p.updateMasks.required=b(m,"required");if(m.containsKey("synced"))p.updateMasks.synced=b(m,"synced");if(m.containsKey("stamp"))p.updateMasks.appearanceStamp=((Number)m.get("stamp")).longValue();}
 static void act(Map a){Player p=a.containsKey("node")&&a.get("node")==null?null:nodes.get(a.getOrDefault("node","self"));List<Player>list=nodes.get("self").renderInfo.getLocalPlayers();switch((String)a.get("op")){
  case"render":core.game.world.update.PlayerRenderer.render(p);break;
  case"rebuild":new core.net.packet.out.UpdateSceneGraph().send(new core.net.packet.context.SceneGraphContext(p,false));break;
  case"set":set(p,(Map)a.get("fields"));break;case"clear":list.clear();break;case"push":list.add(p);break;case"erase":list.remove(n(a.get("index")));break;
  case"replaceList":List<Player>fresh=new LinkedList<>();nodes.get("self").renderInfo.setLocalPlayers(fresh);views.add(fresh);break;
  case"maskArray":nodes.get("self").renderInfo.setMaskUpdates(new core.game.node.entity.Entity[n(a.get("size"))]);break;
  case"infoSet":{core.game.node.entity.player.info.RenderInfo info=nodes.get("self").renderInfo;info.setMaskUpdateCount(n(a.get("count")));info.setPreparedAppearance(b(a,"prepared"));info.setOnFirstCycle(b(a,"first"));break;}
  case"registerMask":nodes.get("self").renderInfo.registerMaskUpdate(p);break;
  case"information":nodes.get("self").renderInfo.updateInformation();break;
  case"fail":throw new Failure();default:throw new AssertionError(a);
 }}
 static Object snap(){Map ns=new TreeMap();for(String k:nodes.keySet()){Player p=nodes.get(k);List<Object>stamps=new ArrayList<>();long[]s=p.renderInfo.getAppearanceStamps();for(int i=0;i<s.length;i++)if(s[i]!=0)stamps.add(Arrays.asList(i,s[i]));List<String>local=new ArrayList<>();for(Player other:p.renderInfo.getLocalPlayers())local.add(name(other));ns.put(k,map("location",coords(p.location),"lastScene",coords(p.playerFlags.lastSceneGraph),"active",p.active,"locals",local,"stamps",stamps));}if(b(input,"metadata")){for(String k:nodes.keySet()){core.game.node.entity.player.info.RenderInfo info=nodes.get(k).renderInfo;List<Object>masks=new ArrayList<>();for(core.game.node.entity.Entity e:info.getMaskUpdates())masks.add(e==null?null:name((Player)e));((Map)ns.get(k)).put("info",map("first",info.isOnFirstCycle(),"prepared",info.preparedAppearance(),"last",coords(info.getLastLocation()),"count",info.getMaskUpdateCount(),"masks",masks));}}List<Object>vs=new ArrayList<>();for(List<Player>l:views){List<String>v=new ArrayList<>();for(Player p:l)v.add(name(p));vs.add(v);}return map("nodes",ns,"views",vs,"events",new ArrayList<>(events),"frames",new ArrayList<>(frames));}
 static String error(Throwable e){if(e instanceof NullPointerException)return"Null";if(e instanceof IndexOutOfBoundsException)return"Index";if(e instanceof ConcurrentModificationException)return"ConcurrentModification";if(e instanceof Failure)return"Binding";return e.getClass().getSimpleName();}
 static void setup(Map c){input=c;nodes=new TreeMap<>();events=new ArrayList<>();frames=new ArrayList<>();calls=new HashMap<>();views=new ArrayList<>();session=new core.net.IoSession();Map rows=(Map)c.get("nodes");for(Object k:rows.keySet()){Player p=new Player((String)k);set(p,(Map)rows.get(k));nodes.put((String)k,p);}Player self=nodes.get("self");self.playerFlags.lastSceneGraph=loc(c.getOrDefault("lastScene",Arrays.asList(3207L,3217L,0L)));for(Object k:(List)c.getOrDefault("locals",new ArrayList<>()))self.renderInfo.getLocalPlayers().add(nodes.get(k));views.add(self.renderInfo.getLocalPlayers());}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(System.out,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);setup(c);List<Object>out=new ArrayList<>();for(Object a:(List)c.get("actions")){events.clear();frames.clear();String failure=null;try{act((Map)a);}catch(Throwable e){failure=error(e);}Map s=(Map)snap();s.put("error",failure);out.add(s);}c.put("expected",out);JSONValue.writeJSONString(c,w);w.newLine();w.flush();}}}
}
